Definition w24 (n : Z) : Z := if win24 n then 1 else 0.
Lemma w24_range : forall n, 0 <= w24 n <= 1.
Proof. intros n. unfold w24. destruct (win24 n); lia. Qed.
Lemma w24_in : forall n, w24 n = 1 -> 5889 <= n <= 7936.
Proof. intros n. unfold w24, win24. destruct (5889 <=? n) eqn:A; destruct (n <=? 7936) eqn:B; cbn; intros H; try discriminate H. apply Z.leb_le in A. apply Z.leb_le in B. lia. Qed.
Lemma w24_ctl : forall len, w24 (4 * chars_to_limbs len) = 1 -> 5889 <= len.   (* [comment removed for export] *)
Proof. intros len H. apply w24_in in H. unfold chars_to_limbs in H. pose proof (Z.div_mod (len + 3) 4 ltac:(lia)). pose proof (Z.mod_pos_bound (len + 3) 4 ltac:(lia)). lia. Qed.
Lemma cnt24_single : forall (b : blk), cnt24 (b :: nil) = w24 (snd b).
Proof. intros b. pose proof (cnt24_cons b nil) as H. rewrite cnt24_nil in H. rewrite H. unfold w24. destruct (win24 (snd b)); reflexivity. Qed.
Lemma cnt24_mpd_blk : forall d, cnt24 (mpd_blk d) = match md_own d with LHeap => w24 (4 * md_n d) | _ => 0 end.
Proof. intros d. unfold mpd_blk. destruct (md_own d); try apply cnt24_nil. exact (cnt24_single (md_p d, 4 * md_n d)). Qed.
